#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 998244353;

ll pw(ll b, ll e, ll m){ ll r=1; b%=m; while(e){ if(e&1) r=r*b%m; b=b*b%m; e>>=1;} return r;}

const int MX = 20005;
ll fact[MX], inv_fact[MX];

ll C(ll a, ll b){
    if(a<0||b<0||b>a) return 0;
    return fact[a]*inv_fact[b]%MOD*inv_fact[a-b]%MOD;
}

int main(){
    fact[0]=1;
    for(int i=1;i<MX;i++) fact[i]=fact[i-1]*i%MOD;
    inv_fact[MX-1]=pw(fact[MX-1],MOD-2,MOD);
    for(int i=MX-1;i>0;i--) inv_fact[i-1]=inv_fact[i]*i%MOD;

    ll p,s,r;
    cin>>p>>s>>r;

    // count(n, rem, m): number of solutions of n vars in [0,m-1] summing to rem
    auto count = [&](ll n, ll rem, ll m)->ll{
        if(rem<0) return 0;
        if(n==0) return rem==0?1:0;
        if(m==0) return 0;
        ll res=0;
        for(ll j=0;j<=n;j++){
            ll t = rem - j*m;
            if(t<0) break;
            ll term = C(n,j)*C(t+n-1, n-1)%MOD;
            if(j&1) res = (res - term % MOD + MOD)%MOD;
            else res = (res + term)%MOD;
        }
        return res;
    };

    ll total = C(s-r+p-1, p-1);
    ll ans = 0;
    for(ll m=r; m<=s; m++){
        for(ll k=0;k<=p-1;k++){
            ll rem = s - m*(k+1);
            if(rem<0) break;
            ll n = p-1-k;
            ll w = count(n, rem, m);
            if(w==0) continue;
            ans = (ans + C(p-1,k)*w%MOD*pw(k+1, MOD-2, MOD))%MOD;
        }
    }
    ans = ans * pw(total, MOD-2, MOD) % MOD;
    cout << ans << endl;
    return 0;
}
